-- Urban Air prototype schema. Idempotent: safe to apply repeatedly.
-- Sample data is regenerated by scripts/reseed.php; nothing here stores visitor data.

CREATE TABLE IF NOT EXISTS airports (
    code CHAR(3) NOT NULL PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    city VARCHAR(80) NOT NULL,
    timezone VARCHAR(40) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS routes (
    id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    origin CHAR(3) NOT NULL,
    destination CHAR(3) NOT NULL,
    distance_mi INT UNSIGNED NOT NULL,
    duration_min INT UNSIGNED NOT NULL,
    UNIQUE KEY uq_route (origin, destination),
    CONSTRAINT fk_route_origin FOREIGN KEY (origin) REFERENCES airports (code),
    CONSTRAINT fk_route_destination FOREIGN KEY (destination) REFERENCES airports (code)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS aircraft_types (
    code VARCHAR(20) NOT NULL PRIMARY KEY,
    manufacturer VARCHAR(60) NOT NULL,
    model VARCHAR(60) NOT NULL,
    seat_capacity SMALLINT UNSIGNED NOT NULL,
    layout_key VARCHAR(40) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS aircraft (
    id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    tail_number VARCHAR(10) NOT NULL UNIQUE,
    name VARCHAR(60) NOT NULL,
    type_code VARCHAR(20) NOT NULL,
    CONSTRAINT fk_aircraft_type FOREIGN KEY (type_code) REFERENCES aircraft_types (code)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS flights (
    id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    flight_number VARCHAR(8) NOT NULL UNIQUE,
    flight_date DATE NOT NULL,
    depart_time TIME NOT NULL,
    arrive_time TIME NOT NULL,
    duration_min SMALLINT UNSIGNED NOT NULL,
    aircraft_id SMALLINT UNSIGNED NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'scheduled',
    CONSTRAINT fk_flight_aircraft FOREIGN KEY (aircraft_id) REFERENCES aircraft (id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS flight_fares (
    flight_id SMALLINT UNSIGNED NOT NULL,
    class_code VARCHAR(12) NOT NULL,
    price_cents INT UNSIGNED NOT NULL,
    seats_total SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (flight_id, class_code),
    CONSTRAINT fk_fare_flight FOREIGN KEY (flight_id) REFERENCES flights (id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS seats (
    id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    flight_id SMALLINT UNSIGNED NOT NULL,
    row_num SMALLINT UNSIGNED NOT NULL,
    col_letter CHAR(1) NOT NULL,
    class_code VARCHAR(12) NOT NULL,
    status ENUM('open', 'taken') NOT NULL,
    feature_codes VARCHAR(255) NOT NULL DEFAULT '',
    UNIQUE KEY uq_seat (flight_id, row_num, col_letter),
    CONSTRAINT fk_seat_flight FOREIGN KEY (flight_id) REFERENCES flights (id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS passengers_manifest (
    id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    flight_id SMALLINT UNSIGNED NOT NULL,
    first_name VARCHAR(40) NOT NULL,
    last_name VARCHAR(40) NOT NULL,
    seat_id INT UNSIGNED NULL,
    class_code VARCHAR(12) NOT NULL,
    ticket_ref CHAR(6) NOT NULL,
    CONSTRAINT fk_manifest_flight FOREIGN KEY (flight_id) REFERENCES flights (id) ON DELETE CASCADE,
    CONSTRAINT fk_manifest_seat FOREIGN KEY (seat_id) REFERENCES seats (id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS rewards_tiers (
    code VARCHAR(20) NOT NULL PRIMARY KEY,
    name VARCHAR(40) NOT NULL,
    min_points INT UNSIGNED NOT NULL,
    benefits TEXT NOT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS partners (
    id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(80) NOT NULL,
    category VARCHAR(40) NOT NULL,
    description VARCHAR(255) NOT NULL,
    logo_key VARCHAR(60) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS error_scenarios (
    code VARCHAR(40) NOT NULL PRIMARY KEY,
    title VARCHAR(120) NOT NULL,
    message VARCHAR(255) NOT NULL,
    probability DECIMAL(4,3) NOT NULL,
    retry_allowed TINYINT(1) NOT NULL DEFAULT 1,
    endpoint_scope VARCHAR(120) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS seed_meta (
    meta_key VARCHAR(40) NOT NULL PRIMARY KEY,
    meta_value VARCHAR(255) NOT NULL
) ENGINE=InnoDB;
